import { useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Faq from './components/Faq';

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "FAQ", href: "#faq" },
  ];
  return (
    <div className="min-h-screen bg-white text-slate-900">
      <header className="sticky top-0 z-50 bg-white/85 backdrop-blur-xl border-b border-slate-200/70">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-xl bg-gradient-to-br from-indigo-600 to-violet-600 inline-block" />
            <span className="font-extrabold text-lg tracking-tight">Casa Verde</span>
          </a>
          <nav className="hidden md:flex items-center gap-8 text-sm font-medium text-slate-600">
            {links.map(l => <a key={l.href} href={l.href} className="hover:text-slate-900 transition-colors">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className="px-4 py-2 rounded-xl bg-slate-900 text-white text-sm font-semibold hover:bg-slate-700 transition-colors">Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className="md:hidden border-t border-slate-200 bg-white px-6 py-4 space-y-3">
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className="block font-medium text-slate-700">{l.label}</a>)}
          </div>
        )}
      </header>
      <main id="top">
      <Faq />
      </main>
      <footer className="border-t border-slate-200 py-10 text-center text-sm text-slate-500">
        <span className="font-bold text-slate-700">Casa Verde</span> &copy; 2026. All rights reserved.
      </footer>
    </div>    );
}

import React, { useState } from 'react';
import { Circle as Question, ChevronRight, ChevronDown, Sparkles } from 'lucide-react';

const FAQ_DATA = [
  {
    id: 1,
    question: "How do I make a reservation?",
    answer: "Reservations can be made directly on our platform or via the 'Book Now' button on the table. We require a valid credit card for verification purposes only, and no-shows will result in a reservation fee. Our chefs are meticulous about timing, so please arrive within 10 minutes of your reservation time.",
    isExpanded: false
  },
  {
    id: 2,
    question: "What kind of pizza do you offer?",
    answer: "Our wood-fired oven is the heart of Casa Verde. We craft artisanal pizzas with heirloom tomatoes, fresh basil, and hand-selected cheeses. Each pie is cooked to perfection in under two minutes, ensuring a crispy crust and robust flavors.",
    isExpanded: false
  },
  {
    id: 3,
    question: "Do you have a kids' menu?",
    answer: "Absolutely! We believe food should be a joyful experience for the whole family. Our kids' menu features mini portions of our signature dishes, and we offer a special children's cocktail for the young sommeliers.",
    isExpanded: false
  },
  {
    id: 4,
    question: "What is your natural wine list like?",
    answer: "Our wine cellar is curated by sommeliers who focus on natural and biodynamic wines. Each bottle tells a story of sustainable farming and unique terroir. We recommend trying our house red blend, which pairs beautifully with our seasonal pasta courses.",
    isExpanded: false
  },
  {
    id: 5,
    question: "Is your restaurant wheelchair accessible?",
    answer: "Yes, Casa Verde is fully wheelchair accessible. Our dining area is spacious with wide aisles, and we have a dedicated accessible restroom. We also provide special menus for guests with dietary restrictions or allergies.",
    isExpanded: false
  }
];

export default function Faq() {
  const [activeId, setActiveId] = useState(null);

  const handleToggle = (id) => {
    setActiveId(id === activeId ? null : id);
  };

  return (
    <div className="min-h-screen bg-slate-950 p-4 sm:p-6 md:p-8 text-slate-100">
      <div className="max-w-7xl mx-auto">
        {/* Decorative gradient background overlay */}
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-gradient-to-br from-indigo-600/20 via-purple-600/10 to-transparent rounded-full blur-3xl pointer-events-none" />

        {/* Heading and accent bar */}
        <div className="mb-8 text-center">
          <h2 className="text-3xl font-bold tracking-tight text-transparent bg-clip-text from-cyan-400 to-indigo-400 mb-4">Frequently Asked Questions</h2>
          <div className="w-16 h-1 bg-indigo-500 rounded-full border border-indigo-600" />
        </div>

        {/* Accordion panel styles */}
        <div className="space-y-5 max-w-md mx-auto">
          {FAQ_DATA.map((faq) => (
            <div key={faq.id} className="group relative border border-white/10 rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-white/20 hover:bg-white/10">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-2 text-slate-400">
                  <Question className="w-5 h-5 animate-pulse text-indigo-400 group-hover:text-indigo-500" />
                  <div>
                    <h3 className="text-sm font-semibold tracking-tight">{faq.question}</h3>
                    {activeId === faq.id && <p className="text-xs text-slate-500">Expanded</p>}
                  </div>
                </div>
                <button
                  onClick={() => handleToggle(faq.id)}
                  className="p-2 rounded-xl bg-white/5 text-slate-400 hover:text-white transition-colors"
                >
                  {activeId === faq.id ? <ChevronDown className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
                </button>
              </div>
              {activeId === faq.id && (
                <div className="text-slate-400 text-sm tracking-wide">
                  {faq.answer}
                  <br />
                  <br />
                  {faq.id === 4 && <div className="inline-flex items-center gap-1"><Sparkles className="w-4 h-4 text-indigo-400" />Pairing suggestions included.</div>}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

